var config = $('Config').first().json;
var items = $input.all();
if (!items || items.length === 0) {
  return [{json: {_empty: true, message: 'No scored articles found'}}];
}
var now = new Date();
var cutoff = new Date(now.getTime() - config.MAX_AGE_HOURS * 60 * 60 * 1000);
var filtered = items.filter(function(item) {
  var score = item.json.composite_score || item.json.header_score || 0;
  if (score < config.MIN_SCORE) return false;
  var created = item.json.created_at ? new Date(item.json.created_at) : now;
  if (created < cutoff) return false;
  return true;
});
filtered.sort(function(a, b) {
  var sa = a.json.composite_score || a.json.header_score || 0;
  var sb = b.json.composite_score || b.json.header_score || 0;
  return sb - sa;
});
if (filtered.length === 0) {
  return [{json: {_empty: true, message: 'No articles passed filter'}}];
}
return filtered;

var config = $('Config').first().json;
var items = $input.all();
if (items.length === 1 && items[0].json._empty) return items;
var categories = config.DIVERSITY_CATEGORIES;
var topN = config.TOP_N;

// Parse category from metadata
function getCategory(item) {
  var meta = item.json.llm_metadata || item.json.metadata || {};
  if (typeof meta === 'string') {
    try { meta = JSON.parse(meta); } catch(e) { meta = {}; }
  }
  var cat = (meta.category || item.json.category || 'uncategorized').toLowerCase();
  return cat;
}

// Build category buckets
var buckets = {};
for (var i = 0; i < categories.length; i++) {
  buckets[categories[i]] = [];
}
buckets['other'] = [];

for (var j = 0; j < items.length; j++) {
  var cat = getCategory(items[j]);
  if (buckets[cat]) {
    buckets[cat].push(items[j]);
  } else {
    buckets['other'].push(items[j]);
  }
}

var selected = [];
var usedUrls = {};

// First pass: 1 per category
for (var k = 0; k < categories.length; k++) {
  var bucket = buckets[categories[k]];
  if (bucket && bucket.length > 0) {
    selected.push(bucket[0]);
    usedUrls[bucket[0].json.url] = true;
  }
}

// Second pass: round-robin least represented
var round = 1;
while (selected.length < topN) {
  var added = false;
  for (var m = 0; m < categories.length; m++) {
    if (selected.length >= topN) break;
    var b = buckets[categories[m]];
    if (b && b.length > round) {
      var candidate = b[round];
      if (!usedUrls[candidate.json.url]) {
        selected.push(candidate);
        usedUrls[candidate.json.url] = true;
        added = true;
      }
    }
  }
  // Fill from other if needed
  if (!added || selected.length < topN) {
    for (var n = 0; n < buckets['other'].length; n++) {
      if (selected.length >= topN) break;
      var oc = buckets['other'][n];
      if (!usedUrls[oc.json.url]) {
        selected.push(oc);
        usedUrls[oc.json.url] = true;
      }
    }
    if (!added) break;
  }
  round++;
}

if (selected.length === 0) {
  return [{json: {_empty: true, message: 'No articles after curation'}}];
}
return selected;

var items = $input.all();
if (items.length <= 1 || (items[0].json._empty)) return items;

function getCategory(item) {
  var meta = item.json.llm_metadata || item.json.metadata || {};
  if (typeof meta === 'string') {
    try { meta = JSON.parse(meta); } catch(e) { meta = {}; }
  }
  return (meta.category || item.json.category || 'uncategorized').toLowerCase();
}

function getKeywords(item) {
  var meta = item.json.llm_metadata || item.json.metadata || {};
  if (typeof meta === 'string') {
    try { meta = JSON.parse(meta); } catch(e) { meta = {}; }
  }
  var tags = meta.tags || meta.keywords || [];
  if (typeof tags === 'string') tags = tags.split(',');
  return tags.map(function(t) { return t.toLowerCase().trim(); });
}

var connections = [];
for (var i = 0; i < items.length; i++) {
  var catI = getCategory(items[i]);
  var kwI = getKeywords(items[i]);
  for (var j = i + 1; j < items.length; j++) {
    var catJ = getCategory(items[j]);
    if (catI === catJ) continue;
    var kwJ = getKeywords(items[j]);
    var overlap = 0;
    for (var k = 0; k < kwI.length; k++) {
      for (var l = 0; l < kwJ.length; l++) {
        if (kwI[k] === kwJ[l] && kwI[k].length > 2) overlap++;
      }
    }
    var maxKw = Math.max(kwI.length, kwJ.length, 1);
    var score = overlap / maxKw;
    if (score > 0.15) {
      connections.push({
        article_a: items[i].json.title || items[i].json.url,
        article_b: items[j].json.title || items[j].json.url,
        categories: catI + ' <-> ' + catJ,
        connection_score: Math.round(score * 100) / 100,
        shared_keywords: kwI.filter(function(k) { return kwJ.indexOf(k) >= 0 && k.length > 2; })
      });
    }
  }
}

// Attach cross-domain flags to items
var connectedUrls = {};
for (var c = 0; c < connections.length; c++) {
  connectedUrls[connections[c].article_a] = connections[c];
  connectedUrls[connections[c].article_b] = connections[c];
}

var result = items.map(function(item) {
  var key = item.json.title || item.json.url;
  var conn = connectedUrls[key];
  var newJson = {};
  for (var p in item.json) { newJson[p] = item.json[p]; }
  newJson.cross_domain = conn ? true : false;
  newJson.cross_domain_connection = conn || null;
  return {json: newJson};
});

return result;

var items = $input.all();
if (items.length === 1 && items[0].json._empty) {
  return [{json: {_skip: true, message: items[0].json.message}}];
}
return items.map(function(item) {
  return {json: {url: item.json.url}};
});
